1	//! The Remote devices dialog: who this host is to a device, where it
2	//! listens, the pairing window with its QR code, and the devices paired
3	//! so far with their scope and a Revoke. Nothing here decides anything:
4	//! every change is an action, and the host's state is read back from
5	//! the core each frame.
6	
7	use egui::{Context, RichText, Ui};
8	
9	use super::{DrawCtx, GAP, cards::since_text, theme};
10	use crate::adapters::remote;
11	use crate::core::{AppAction, AppCore, invite_url};
12	use crate::ports::remote::Scope;
13	
14	/// Shown in place of the address while the port answers this Mac
15	/// alone: the invite then names the loopback address, which no phone
16	/// reaches.
17	const MAC_ONLY_NOTICE: &str =
18	    "This Mac only: allow devices on the local network for a phone to reach the port.";
19	
20	/// What the dialog edits between frames: the name and port fields, the
21	/// scope the next pairing grants, and the QR image for the open code.
22	pub struct RemoteDraft {
23	    pub name: String,
24	    pub port: String,
25	    pub scope: Scope,
26	    /// The QR texture for the code it was made for.
27	    qr: Option<(String, egui::TextureHandle)>,
28	}
29	
30	impl RemoteDraft {
31	    #[must_use]
32	    pub fn open(core: &AppCore) -> Self {
33	        let identity = core.identity();
34	        Self {
35	            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
36	            port: identity
37	                .map(|i| i.listen.port.to_string())
38	                .unwrap_or_default(),
39	            scope: Scope::Read,
40	            qr: None,
41	        }
42	    }
43	}
44	
45	/// The dialog's width: the QR and the device rows fit it.
46	const DIALOG_WIDTH: f32 = 620.0;
47	/// Pixels per QR module; the quiet zone is the standard four.
48	const QR_SCALE: usize = 4;
49	const QR_QUIET: usize = 4;
50	
51	pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
52	    let Some(mut draft) = cx.state.remote_dialog.take() else {
53	        return;
54	    };
55	    let mut keep = true;
56	    egui::Window::new("")
57	        .id(egui::Id::new("remote-devices"))
58	        .title_bar(false)
59	        .collapsible(false)
60	        .resizable(true)
61	        .default_width(DIALOG_WIDTH)
62	        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
63	        .show(ctx, |ui| {
64	            let screen = ctx.content_rect().width();
65	            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
66	            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
67	            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
68	            ui.add_space(8.0);
69	            host(cx, ui, &mut draft);
70	            ui.add_space(8.0);
71	            pairing(cx, ui, &mut draft);
72	            ui.add_space(8.0);
73	            devices(cx, ui);
74	            ui.add_space(8.0);
75	            let p = theme::palette(ui);
76	            ui.label(
77	                RichText::new(
78	                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
79	                )
80	                .small()
81	                .color(p.n600),
82	            );
83	            ui.label(
84	                RichText::new(
85	                    "A browser cannot pin this Mac's key: it will warn about the certificate, and proceeding past the warning is the trust step, so proceed only if the address is this Mac's. Pair a browser only on a network you trust. The code works once.",
86	                )
87	                .small()
88	                .color(p.n600),
89	            );
90	            ui.horizontal(|ui| {
91	                if theme::ghost_muted(ui, "Close").clicked() {
92	                    keep = false;
93	                }
94	            });
95	        });
96	    if keep {
97	        cx.state.remote_dialog = Some(draft);
98	    }
99	}
100	
101	/// This host: its name, id and key, and where it listens.
102	fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
103	    theme::section(ui, "This Mac");
104	    let Some(identity) = cx.core.identity().cloned() else {
105	        ui.label("The host has no identity yet; see the log.");
106	        return;
107	    };
108	    ui.horizontal(|ui| {
109	        let id = ui.label("Name").id;
110	        let field = ui
111	            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
112	            .labelled_by(id);
113	        if field.lost_focus() && draft.name.trim() != identity.server_name {
114	            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
115	        }
116	    });
117	    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
118	    ui.label(theme::meta_text(
119	        ui,
120	        format!("Key {}", short_hash(&identity.spki_sha256)),
121	    ));
122	    ui.horizontal(|ui| {
123	        let mut lan = identity.listen.lan;
124	        if ui
125	            .checkbox(&mut lan, "Allow devices on the local network")
126	            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
127	            .changed()
128	        {
129	            cx.dispatch(AppAction::SetRemoteListen {
130	                lan,
131	                port: identity.listen.port,
