1	'use strict';
2	
3	// The remote port's web page: pairs from the fragment of the URL the
4	// host's QR code carries, lists the sessions with the waiting ones
5	// first, shows a session's last response or screen, and sends a reply.
6	// It speaks what the headset speaks (docs/remote-client.md §4) and
7	// keeps nothing but the host's public identity; the credential is a
8	// cookie this script cannot read. Plain DOM, `textContent` only, no
9	// dependency. The pure parts at the top are what `app.test.js` covers.
10	
11	// Every path the page reads, in one place so a test can check that the
12	// host answers each. `{id}` is a project's id under `/projects/` and a
13	// session's elsewhere.
14	const API = {
15	  info: '/api/v1/info',
16	  pair: '/api/v1/pair',
17	  me: '/api/v1/me',
18	  projects: '/api/v1/projects',
19	  sessions: '/api/v1/projects/{id}/sessions',
20	  waiting: '/api/v1/waiting',
21	  lastResponse: '/api/v1/sessions/{id}/last-response',
22	  screen: '/api/v1/sessions/{id}/screen',
23	  send: '/api/v1/sessions/{id}/send',
24	  events: '/api/v1/events',
25	};
26	
27	const STORAGE_KEY = 'switchboard-host';
28	const POLL_MS = 3000;
29	const POLL_SLOW_MS = 20000;
30	const SOCKET_RETRY_MS = 5000;
31	const SOCKET_RETRY_MAX_MS = 60000;
32	
33	// --- pure parts
34	
35	// The pairing values in a URL fragment: `#code=…&key=…&id=…`, or null
36	// when any of the three is missing.
37	function parseFragment(hash) {
38	  const text = (hash || '').replace(/^#/, '');
39	  if (!text) return null;
40	  const values = {};
41	  for (const pair of text.split('&')) {
42	    const at = pair.indexOf('=');
43	    if (at <= 0) continue;
44	    const name = decodeURIComponent(pair.slice(0, at));
45	    const value = decodeURIComponent(pair.slice(at + 1));
46	    values[name] = value;
47	  }
48	  if (!values.code || !values.key || !values.id) return null;
49	  return { code: values.code, key: values.key, id: values.id };
50	}
51	
52	// What the host lists this browser as: the browser "on" the device,
53	// from the user agent, with a Macintosh that reports touch counted as
54	// an iPad (Safari on iPadOS says Macintosh).
55	function deviceName(userAgent, touchPoints) {
56	  const ua = userAgent || '';
57	  let browser = 'Safari';
58	  if (/Edg\//.test(ua)) browser = 'Edge';
59	  else if (/Chrome\//.test(ua)) browser = 'Chrome';
60	  else if (/Firefox\//.test(ua)) browser = 'Firefox';
61	  let device = '';
62	  if (/iPhone/.test(ua)) device = 'iPhone';
63	  else if (/iPad/.test(ua)) device = 'iPad';
64	  else if (/Macintosh/.test(ua)) device = touchPoints > 1 ? 'iPad' : 'Mac';
65	  else if (/Android/.test(ua)) device = 'Android';
66	  else if (/Windows/.test(ua)) device = 'Windows';
67	  else if (/Linux/.test(ua)) device = 'Linux';
68	  if (!browser && !device) return 'Browser';
69	  return device ? `${browser} on ${device}` : browser;
70	}
71	
72	// Why a request was refused 401, told from `/info`, which the page can
73	// read unpaired: `stored` is what the page kept of the host it paired
74	// with, `info` the body `/info` answered now or null when it did not.
75	// The host cannot say "revoked" (a revoked token and an unknown one are
76	// the same refusal), so the page infers it from the identity standing.
77	function inferUnauthorized(stored, info) {
78	  if (!info) return 'unreachable';
79	  if (!stored) return 'not_paired';
80	  if (stored.server_id === info.server_id && stored.spki_sha256 === info.spki_sha256) {
81	    return 'removed';
82	  }
83	  return 'identity_changed';
84	}
85	
86	const UNAUTHORIZED_TEXT = {
87	  unreachable: ['Can\'t reach the host', 'The Mac did not answer. Check that it is on and on this network.'],
88	  not_paired: ['Not paired', 'Open Remote devices on the Mac, allow pairing, and scan its code with this phone.'],
89	  removed: ['Removed on the host', 'This device was removed on the Mac. Open its pairing window and scan the code again.'],
90	  identity_changed: ['Identity changed', 'The host at this address is not the one this browser paired with, or its key was remade. Pair again from its window.'],
91	};
92	
93	// Whether a reply at (epoch, revision) is at or past what the page
94	// holds (§4.4): a reply from an earlier revision is dropped, and a new
95	// epoch (the host restarted) always applies.
96	function accepts(held, reply) {
97	  if (!held) return true;
98	  if (held.epoch !== reply.epoch) return true;
99	  return reply.revision >= held.revision;
100	}
101	
102	// The list as the page shows it: projects with a waiting session
103	// first, waiting sessions first within a project, then by last
104	// activity, newest first, name as the tie-break. Pure over the two
105	// replies so a test can call it.
106	function orderList(projects, sessionsByProject) {
107	  const groups = projects.map((project) => {
108	    const sessions = (sessionsByProject[project.id] || []).slice();
109	    sessions.sort((a, b) => {
110	      if (Boolean(a.waiting) !== Boolean(b.waiting)) return a.waiting ? -1 : 1;
111	      const ta = a.last_activity_ms || 0;
112	      const tb = b.last_activity_ms || 0;
113	      if (ta !== tb) return tb - ta;
114	      return String(a.name).localeCompare(String(b.name));
115	    });
116	    return { project, sessions, waiting: sessions.some((s) => s.waiting) };
117	  });
118	  groups.sort((a, b) => {
119	    if (a.waiting !== b.waiting) return a.waiting ? -1 : 1;
120	    return String(a.project.name).localeCompare(String(b.project.name));
121	  });
122	  return groups;
123	}
124	
125	// "3 m ago", "2 h ago"; '' with no time.
126	function sinceText(ms, now) {
127	  if (!ms) return '';
128	  const s = Math.max(0, Math.floor((now - ms) / 1000));
129	  if (s < 60) return 'just now';
130	  const m = Math.floor(s / 60);
131	  if (m < 60) return `${m} m ago`;
132	  const h = Math.floor(m / 60);
133	  if (h < 48) return `${h} h ago`;
134	  return `${Math.floor(h / 24)} d ago`;
135	}
136	
137	// The reply box's operation id: random hex, kept across a retry so a
138	// send whose reply was lost is answered from the host's log rather
139	// than typed twice. `getRandomValues` exists outside a secure context.
140	function newOp(randomValues) {
141	  const bytes = new Uint8Array(16);
142	  randomValues(bytes);
143	  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
144	}
145	
146	if (typeof module !== 'undefined' && module.exports) {
147	  module.exports = {
148	    API,
149	    parseFragment,
150	    deviceName,
151	    inferUnauthorized,
152	    accepts,
153	    orderList,
154	    sinceText,
155	    newOp,
156	  };
157	}
158	
159	// --- the page
