162	  const $ = (id) => document.getElementById(id);
163	
164	  const state = {
165	    me: null,
166	    stored: null,
167	    held: null,
168	    groups: [],
169	    open: null,
170	    openView: null,
171	    pendingOp: null,
172	    socket: null,
173	    socketRetryMs: SOCKET_RETRY_MS,
174	    pollTimer: null,
175	    pollMs: POLL_MS,
176	  };
177	
178	  function show(section) {
179	    for (const id of ['boot', 'notice', 'list', 'session']) {
180	      $(id).hidden = id !== section;
181	    }
182	  }
183	
184	  function notice(title, text) {
185	    $('notice-title').textContent = title;
186	    $('notice-text').textContent = text;
187	    show('notice');
188	  }
189	
190	  function loadStored() {
191	    try {
192	      const text = localStorage.getItem(STORAGE_KEY);
193	      return text ? JSON.parse(text) : null;
194	    } catch (e) {
195	      return null;
196	    }
197	  }
198	
199	  function saveStored(value) {
200	    try {
201	      localStorage.setItem(STORAGE_KEY, JSON.stringify(value));
202	    } catch (e) {
203	      // Private browsing may refuse; the page then forgets on reload.
204	    }
205	    state.stored = value;
206	  }
207	
208	  // One request to the host; the cookie rides along as the browser's
209	  // own credential. The reply is the parsed envelope with its status.
210	  async function api(method, path, body) {
211	    const init = { method, credentials: 'same-origin', headers: {} };
212	    if (body !== undefined) {
213	      init.headers['Content-Type'] = 'application/json';
214	      init.body = JSON.stringify(body);
215	    }
216	    let response;
217	    try {
218	      response = await fetch(path, init);
219	    } catch (e) {
220	      return { status: 0, json: null };
221	    }
222	    let json = null;
223	    try {
224	      json = await response.json();
225	    } catch (e) {
226	      json = null;
227	    }
228	    return { status: response.status, json };
229	  }
230	
231	  function errorCode(reply) {
232	    return reply.json && reply.json.error ? reply.json.error.code : '';
233	  }
234	
235	  async function unauthorized() {
236	    stopRefresh();
237	    const info = await api('GET', API.info);
238	    const kind = inferUnauthorized(state.stored, info.status === 200 ? info.json.body : null);
239	    const [title, text] = UNAUTHORIZED_TEXT[kind];
240	    notice(title, text);
241	  }
242	
243	  // The reply, or null after a refusal was shown.
244	  async function read(path) {
245	    const reply = await api('GET', path);
246	    if (reply.status === 401) {
247	      await unauthorized();
248	      return null;
249	    }
250	    if (reply.status === 0) {
251	      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
252	      return null;
253	    }
254	    return reply;
255	  }
