258	    state.stored = loadStored();
259	    const fragment = parseFragment(location.hash);
260	    if (fragment) {
261	      // The code leaves the address bar before anything else happens.
262	      history.replaceState(null, '', location.pathname);
263	      await pair(fragment);
264	      return;
265	    }
266	    const me = await api('GET', API.me);
267	    if (me.status === 200) {
268	      becamePaired(me.json.body);
269	      return;
270	    }
271	    if (me.status === 401) {
272	      await unauthorized();
273	      return;
274	    }
275	    notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
276	  }
277	
278	  const PAIR_TEXT = {
279	    pairing_closed: 'The pairing window on the Mac is closed. Allow pairing again and scan the new code.',
280	    wrong_code: 'The code does not match. Scan the code the Mac shows now.',
281	    wrong_key: 'This is not the host the code was scanned from.',
282	    rate_limited: 'Too many pairing attempts. Wait a minute and scan again.',
283	  };
284	
285	  async function pair(fragment) {
286	    $('boot-text').textContent = 'Pairing…';
287	    const info = await api('GET', API.info);
288	    if (info.status !== 200) {
289	      notice(UNAUTHORIZED_TEXT.unreachable[0], UNAUTHORIZED_TEXT.unreachable[1]);
290	      return;
291	    }
292	    const host = info.json.body;
293	    if (host.spki_sha256 !== fragment.key || host.server_id !== fragment.id) {
294	      notice('Different host', 'This address is a different Switchboard than the code was for. Nothing was sent.');
295	      return;
296	    }
297	    const reply = await api('POST', API.pair, {
298	      code: fragment.code,
299	      spki_sha256: fragment.key,
300	      device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
301	      transport: 'cookie',
302	    });
303	    if (reply.status !== 200) {
304	      const code = errorCode(reply);
305	      notice('Not paired', PAIR_TEXT[code] || `The host refused the pairing (${code || reply.status}).`);
306	      return;
307	    }
308	    saveStored({
309	      server_id: host.server_id,
310	      spki_sha256: host.spki_sha256,
311	      server_name: host.server_name,
312	    });
313	    const me = await api('GET', API.me);
314	    if (me.status !== 200) {
315	      await unauthorized();
316	      return;
317	    }
318	    becamePaired(me.json.body);
319	  }
320	
321	  function becamePaired(me) {
322	    state.me = me;
323	    $('host-name').textContent = me.server_name;
324	    $('scope').textContent = me.scope;
325	    $('header').hidden = false;
326	    show('list');
327	    refreshAll();
328	    startRefresh();
329	  }
330	
331	  async function refreshMe() {
332	    const reply = await read(API.me);
333	    if (reply && reply.status === 200) {
334	      state.me = reply.json.body;
335	      $('scope').textContent = state.me.scope;
336	    }
337	  }
338	
339	  // --- the list
340	
341	  async function refreshList() {
342	    const projects = await read(API.projects);
343	    if (!projects || projects.status !== 200) return;
344	    const list = projects.json.body.projects || [];
345	    const sessionsByProject = {};
346	    for (const project of list) {
347	      const reply = await read(API.sessions.replace('{id}', project.id));
348	      if (!reply) return;
349	      sessionsByProject[project.id] = reply.status === 200 ? reply.json.body.sessions || [] : [];
350	    }
351	    state.groups = orderList(list, sessionsByProject);
352	    renderList();
353	  }
354	
355	  function renderList() {
356	    const root = $('projects');
357	    root.textContent = '';
358	    const now = Date.now();
359	    let count = 0;
360	    for (const group of state.groups) {
361	      if (group.sessions.length === 0) continue;
362	      const title = document.createElement('h2');
363	      title.textContent = group.project.name;
364	      root.appendChild(title);
365	      for (const session of group.sessions) {
366	        count += 1;
367	        const row = document.createElement('button');
368	        row.type = 'button';
369	        row.className = session.waiting ? 'session-row is-waiting' : 'session-row';
370	        if (session.waiting) {
371	          const waiting = document.createElement('span');
372	          waiting.className = 'line waiting';
373	          waiting.textContent = session.waiting_reason
374	            ? `Waiting on you: ${session.waiting_reason}`
375	            : 'Waiting on you';
376	          row.appendChild(waiting);
377	        }
378	        const name = document.createElement('span');
379	        name.className = 'line name';
380	        name.textContent = session.name;
381	        row.appendChild(name);
382	        const meta = document.createElement('span');
383	        meta.className = 'line meta';
384	        const since = sinceText(session.last_activity_ms, now);
385	        meta.textContent = [session.kind, session.card, since].filter(Boolean).join(' · ');
386	        row.appendChild(meta);
387	        row.addEventListener('click', () => openSession(session));
388	        root.appendChild(row);
389	      }
390	    }
391	    $('list-empty').hidden = count !== 0;
392	  }
393	
394	  // --- a session
395	
396	  function openSession(session) {
397	    state.open = session;
398	    state.pendingOp = null;
399	    $('session-name').textContent = session.name;
400	    $('session-text').textContent = '';
401	    $('session-truncated').hidden = true;
402	    $('send-status').textContent = '';
403	    $('reply-text').value = '';
404	    show('session');
405	    renderSessionMeta();
406	    refreshSession();
407	  }
408	
409	  function renderSessionMeta() {
410	    const session = state.open;
411	    if (!session) return;
412	    $('session-meta').textContent = [session.kind, session.card].filter(Boolean).join(' · ');
413	    const waiting = $('session-waiting');
414	    waiting.hidden = !session.waiting;
415	    waiting.textContent = session.waiting_reason
416	      ? `Waiting on you: ${session.waiting_reason}`
417	      : 'Waiting on you';
418	    const canSend = state.me && state.me.scope === 'control' && !session.prompt_refusal;
419	    $('reply').hidden = !canSend;
420	    const refusal = $('refusal');
421	    refusal.hidden = !(state.me && state.me.scope === 'control' && session.prompt_refusal);
422	    refusal.textContent = session.prompt_refusal ? `No reply: ${session.prompt_refusal}` : '';
423	  }
424	
425	  async function refreshSession() {
426	    const session = state.open;
427	    if (!session) return;
428	    const path = session.kind === 'claude' ? API.lastResponse : API.screen;
429	    const reply = await read(path.replace('{id}', session.id));
430	    if (!reply || state.open !== session) return;
431	    if (reply.status !== 200) {
432	      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
433	      $('session-text').textContent = message;
434	      return;
435	    }
436	    if (state.openView && !accepts(state.openView, reply.json)) return;
437	    state.openView = { epoch: reply.json.epoch, revision: reply.json.revision };
438	    $('session-text').textContent = reply.json.body.text || '';
439	    $('session-truncated').hidden = !reply.json.body.truncated;
440	  }
441	
442	  // The session as the list now says it is, so the card word and the
443	  // refusal follow a refetch.
444	  function syncOpenFromList() {
445	    if (!state.open) return;
446	    for (const group of state.groups) {
447	      const found = group.sessions.find((s) => s.id === state.open.id);
448	      if (found) {
449	        state.open = found;
450	        renderSessionMeta();
451	        return;
452	      }
453	    }
454	  }
455	
456	  async function send(event) {
457	    event.preventDefault();
458	    const session = state.open;
459	    const text = $('reply-text').value;
460	    if (!session || !text.trim()) return;
461	    if (!state.pendingOp) state.pendingOp = newOp((b) => crypto.getRandomValues(b));
462	    const op = state.pendingOp;
463	    $('send').disabled = true;
464	    $('send-status').textContent = 'Sending…';
465	    const reply = await api('POST', API.send.replace('{id}', session.id), { op, text });
466	    $('send').disabled = false;
467	    if (reply.status === 401) {
468	      await unauthorized();
469	      return;
470	    }
471	    if (reply.status === 0) {
472	      $('send-status').textContent = 'No answer; Send again repeats the same operation.';
473	      return;
474	    }
475	    const code = errorCode(reply);
476	    if (reply.status === 403 && code === 'scope') {
477	      $('send-status').textContent = 'This device reads only now.';
478	      await refreshMe();
479	      renderSessionMeta();
480	      return;
481	    }
482	    if (reply.status !== 200) {
483	      const message = reply.json && reply.json.error ? reply.json.error.message : `HTTP ${reply.status}`;
484	      $('send-status').textContent = message;
485	      state.pendingOp = null;
486	      return;
487	    }
488	    state.pendingOp = null;
489	    $('reply-text').value = '';
490	    $('send-status').textContent = 'Sent';
491	  }
492	
493	  // --- refresh: polling as the base, the socket as the enhancement
494	
495	  async function refreshAll() {
496	    await refreshList();
497	    syncOpenFromList();
498	    await refreshSession();
499	  }
500	
501	  async function poll() {
502	    if (document.hidden) return;
503	    const reply = await read(API.waiting);
504	    if (!reply || reply.status !== 200) return;
505	    const seen = { epoch: reply.json.epoch, revision: reply.json.revision };
506	    if (state.held && state.held.epoch === seen.epoch && state.held.revision === seen.revision) {
507	      return;
508	    }
509	    state.held = seen;
510	    await refreshAll();
511	  }
512	
513	  function startRefresh() {
514	    stopRefresh();
515	    state.pollTimer = setInterval(poll, state.pollMs);
516	    openSocket();
517	  }
518	
519	  function stopRefresh() {
520	    if (state.pollTimer) clearInterval(state.pollTimer);
521	    state.pollTimer = null;
522	    if (state.socket) {
523	      const socket = state.socket;
524	      state.socket = null;
525	      socket.onclose = null;
526	      socket.close();
527	    }
528	  }
529	
530	  function setPoll(ms) {
531	    if (state.pollMs === ms && state.pollTimer) return;
532	    state.pollMs = ms;
533	    if (state.pollTimer) clearInterval(state.pollTimer);
534	    state.pollTimer = setInterval(poll, ms);
535	  }
536	
537	  function openSocket() {
538	    if (state.socket || typeof WebSocket === 'undefined') return;
539	    let socket;
540	    try {
541	      socket = new WebSocket(`wss://${location.host}${API.events}`);
542	    } catch (e) {
543	      return;
544	    }
545	    state.socket = socket;
546	    socket.onopen = () => {
547	      state.socketRetryMs = SOCKET_RETRY_MS;
548	      setPoll(POLL_SLOW_MS);
549	    };
550	    socket.onmessage = (message) => {
551	      let frame;
552	      try {
553	        frame = JSON.parse(message.data);
554	      } catch (e) {
555	        return;
556	      }
557	      if (frame.type === 'changed' || frame.type === 'removed') {
558	        refreshAll();
559	      } else if (frame.type === 'resync_required') {
560	        refreshAll();
561	      }
562	    };
563	    socket.onerror = () => {};
564	    socket.onclose = () => {
565	      if (state.socket !== socket) return;
566	      state.socket = null;
567	      setPoll(POLL_MS);
568	      refreshAll();
569	      const wait = state.socketRetryMs;
570	      state.socketRetryMs = Math.min(wait * 2, SOCKET_RETRY_MAX_MS);
571	      setTimeout(() => {
572	        if (state.pollTimer) openSocket();
573	      }, wait);
574	    };
575	  }
576	
577	  document.addEventListener('visibilitychange', () => {
578	    if (!document.hidden && state.pollTimer) poll();
579	  });
580	  $('back').addEventListener('click', () => {
581	    state.open = null;
582	    state.openView = null;
583	    show('list');
584	  });
585	  $('reply').addEventListener('submit', send);
586	  boot();
587	}
