101	/// This host: its name, id and key, and where it listens.
102	fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
103	    theme::section(ui, "This Mac");
104	    let Some(identity) = cx.core.identity().cloned() else {
105	        ui.label("The host has no identity yet; see the log.");
106	        return;
107	    };
108	    ui.horizontal(|ui| {
109	        let id = ui.label("Name").id;
110	        let field = ui
111	            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
112	            .labelled_by(id);
113	        if field.lost_focus() && draft.name.trim() != identity.server_name {
114	            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
115	        }
116	    });
117	    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
118	    ui.label(theme::meta_text(
119	        ui,
120	        format!("Key {}", short_hash(&identity.spki_sha256)),
121	    ));
122	    ui.horizontal(|ui| {
123	        let mut lan = identity.listen.lan;
124	        if ui
125	            .checkbox(&mut lan, "Allow devices on the local network")
126	            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
127	            .changed()
128	        {
129	            cx.dispatch(AppAction::SetRemoteListen {
130	                lan,
131	                port: identity.listen.port,
132	            });
133	        }
134	        let id = ui.label("Port").id;
135	        let field = ui
136	            .add(egui::TextEdit::singleline(&mut draft.port).desired_width(64.0))
137	            .labelled_by(id);
138	        if field.lost_focus() {
139	            match draft.port.trim().parse::<u16>() {
140	                Ok(port) if port != 0 && port != identity.listen.port => {
141	                    cx.dispatch(AppAction::SetRemoteListen {
142	                        lan: identity.listen.lan,
143	                        port,
144	                    });
145	                }
146	                Ok(_) => {}
147	                Err(_) => draft.port = identity.listen.port.to_string(),
148	            }
149	        }
150	    });
151	}
