153	/// The pairing window: open it with a scope, or show the code it holds.
154	fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
155	    theme::section(ui, "Pairing");
156	    let p = theme::palette(ui);
157	    if cx.core.identity_rotated() {
158	        ui.label(
159	            RichText::new(
160	                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
161	            )
162	            .color(p.accent_2_text),
163	        );
164	    }
165	    let Some(identity) = cx.core.identity().cloned() else {
166	        return;
167	    };
168	    if let Some(window) = cx.core.pairing().cloned() {
169	        let port = cx.remote_port.unwrap_or(identity.listen.port);
170	        // The address a phone reaches, only while the port listens on
171	        // the network; loopback answers this Mac alone.
172	        let address = identity.listen.lan.then(remote::local_address).flatten();
173	        let payload = invite_url(&identity, &window, address, port);
174	        if draft
175	            .qr
176	            .as_ref()
177	            .is_none_or(|(code, _)| *code != window.code)
178	        {
179	            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
180	        }
181	        ui.horizontal(|ui| {
182	            if let Some((_, texture)) = &draft.qr {
183	                ui.image(egui::load::SizedTexture::from_handle(texture));
184	            }
185	            ui.vertical(|ui| {
186	                ui.label(
187	                    RichText::new(spaced(&window.code))
188	                        .text_style(theme::h1())
189	                        .family(egui::FontFamily::Monospace),
190	                );
191	                ui.label(theme::meta_text(
192	                    ui,
193	                    format!("Key {}", short_hash(&identity.spki_sha256)),
194	                ));
195	                match address {
196	                    Some(ip) => {
197	                        let at = std::net::SocketAddr::new(ip, port);
198	                        ui.label(theme::meta_text(ui, format!("Address {at}")));
199	                    }
200	                    None if identity.listen.lan => {}
201	                    None => {
202	                        ui.label(theme::meta_text(ui, MAC_ONLY_NOTICE));
203	                    }
204	                }
205	                ui.label(theme::meta_text(
206	                    ui,
207	                    format!(
208	                        "Scan with a phone's camera to open the page, or type the key and the code into a client. Grants {} scope. Open for five minutes or three wrong codes.",
209	                        window.scope.word()
210	                    ),
211	                ));
212	                ui.horizontal(|ui| {
213	                    // The QR's text, for a client without a camera (the
214	                    // command-line browser takes it as one argument).
215	                    if theme::secondary(ui, "Copy invite")
216	                        .on_hover_text("The QR code's URL, to paste into a client or a browser")
217	                        .clicked()
218	                    {
219	                        ui.ctx().copy_text(payload.clone());
220	                    }
221	                    if theme::secondary(ui, "Stop pairing").clicked() {
222	                        cx.dispatch(AppAction::ClosePairing);
223	                    }
224	                });
225	            });
226	        });
227	    } else {
228	        ui.horizontal(|ui| {
229	            ui.radio_value(&mut draft.scope, Scope::Read, "Read-only")
230	                .on_hover_text("Every view and the screen; nothing is sent into a session");
231	            ui.radio_value(&mut draft.scope, Scope::Control, "Control")
232	                .on_hover_text("Reads, and later the commands that type into a session");
233	            if theme::primary(ui, "Allow pairing for 5 minutes").clicked() {
234	                cx.dispatch(AppAction::OpenPairing {
235	                    code: remote::pairing_code(),
236	                    scope: draft.scope,
237	                });
238	            }
239	        });
240	    }
241	}
