243	/// The devices paired so far, each with its scope and a Revoke.
244	fn devices(cx: &mut DrawCtx<'_>, ui: &mut Ui) {
245	    theme::section(ui, "Paired devices");
246	    let devices = cx.core.devices().to_vec();
247	    if devices.is_empty() {
248	        ui.label(theme::meta_text(ui, "No device is paired."));
249	        return;
250	    }
251	    egui::Grid::new("remote-devices")
252	        .num_columns(5)
253	        .spacing([GAP, GAP])
254	        .show(ui, |ui| {
255	            for device in devices {
256	                ui.label(&device.name);
257	                let mut scope = device.scope;
258	                egui::ComboBox::from_id_salt(("remote-scope", device.id))
259	                    .selected_text(scope.word())
260	                    .show_ui(ui, |ui| {
261	                        ui.selectable_value(&mut scope, Scope::Read, "read");
262	                        ui.selectable_value(&mut scope, Scope::Control, "control");
263	                    });
264	                if scope != device.scope {
265	                    cx.dispatch(AppAction::SetDeviceScope {
266	                        device: device.id,
267	                        scope,
268	                    });
269	                }
270	                ui.label(theme::meta_text(
271	                    ui,
272	                    format!("paired {}", since_text(device.created)),
273	                ));
274	                ui.label(theme::meta_text(
275	                    ui,
276	                    match device.last_seen {
277	                        Some(seen) => format!("seen {}", since_text(seen)),
278	                        None => "never seen".into(),
279	                    },
280	                ));
281	                if theme::ghost_muted(ui, "Revoke")
282	                    .on_hover_text("The device's next request fails; pair it again to restore it")
283	                    .clicked()
284	                {
285	                    cx.dispatch(AppAction::RevokeDevice(device.id));
286	                }
287	                ui.end_row();
288	            }
