292	/// The QR code for `payload` as a texture: black modules on white with
293	/// the quiet zone, scaled so a phone reads it from the screen.
294	fn qr_texture(ctx: &Context, payload: &str) -> Option<egui::TextureHandle> {
295	    let code = qrcode::QrCode::new(payload.as_bytes()).ok()?;
296	    let width = code.width();
297	    let modules = code.to_colors();
298	    let side = (width + 2 * QR_QUIET) * QR_SCALE;
299	    let mut pixels = vec![egui::Color32::WHITE; side * side];
300	    for (i, module) in modules.iter().enumerate() {
301	        if *module != qrcode::Color::Dark {
302	            continue;
303	        }
304	        let (x, y) = (i % width + QR_QUIET, i / width + QR_QUIET);
305	        for dy in 0..QR_SCALE {
306	            for dx in 0..QR_SCALE {
307	                pixels[(y * QR_SCALE + dy) * side + x * QR_SCALE + dx] = egui::Color32::BLACK;
308	            }
309	        }
310	    }
311	    let image = egui::ColorImage::new([side, side], pixels);
312	    Some(ctx.load_texture("remote-pairing-qr", image, egui::TextureOptions::NEAREST))
313	}
