315	/// The first sixteen hex digits of a key hash in groups of four: what
316	/// a person compares against the client's screen.
317	fn short_hash(hex: &str) -> String {
318	    hex.chars()
319	        .take(16)
320	        .collect::<Vec<_>>()
321	        .chunks(4)
322	        .map(|c| c.iter().collect::<String>())
323	        .collect::<Vec<_>>()
324	        .join(" ")
325	}
326	
327	/// "ABCD EFGH": the code in two halves, as it is read aloud.
328	fn spaced(code: &str) -> String {
329	    let (a, b) = code.split_at(code.len() / 2);
330	    format!("{a} {b}")
331	}
