1	//! The web control surface the remote port serves: three files under
2	//! `web/`, embedded at build time and answered on the connection thread
3	//! as constant bytes. Nothing here is a request handler; the table says
4	//! which path is which file, and the listener writes it.
5	
6	/// One embedded file: its path on the port, its type, its bytes.
7	pub struct Page {
8	    pub path: &'static str,
9	    pub content_type: &'static str,
10	    pub body: &'static str,
11	}
12	
13	/// The page's own files and nothing else: no inline script or style,
14	/// no outside resource, requests only to its own origin (the events
15	/// socket included), an inline icon, and no framing of the page.
16	pub const CONTENT_SECURITY_POLICY: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
17	
18	/// Every page the port serves, by exact path.
19	pub const PAGES: &[Page] = &[
20	    Page {
21	        path: "/",
22	        content_type: "text/html; charset=utf-8",
23	        body: include_str!("../../web/index.html"),
24	    },
25	    Page {
26	        path: "/app.js",
27	        content_type: "text/javascript; charset=utf-8",
28	        body: include_str!("../../web/app.js"),
29	    },
30	    Page {
31	        path: "/app.css",
32	        content_type: "text/css; charset=utf-8",
33	        body: include_str!("../../web/app.css"),
34	    },
35	];
36	
37	/// The page at `path`, matched exactly: a query was already split off
38	/// and is ignored.
39	#[must_use]
40	pub fn page(path: &str) -> Option<&'static Page> {
41	    PAGES.iter().find(|p| p.path == path)
42	}
43	
44	#[cfg(test)]
45	mod tests {
46	    use super::*;
47	
48	    #[test]
49	    fn pages_match_exactly_and_hold_their_files() {
50	        assert_eq!(
51	            page("/").map(|p| p.content_type),
52	            Some("text/html; charset=utf-8")
53	        );
54	        assert!(page("/app.js").is_some_and(|p| p.body.contains("'use strict'")));
55	        assert!(page("/app.css").is_some());
56	        assert!(page("/index.html").is_none());
57	        assert!(page("/app.js/").is_none());
58	        assert!(page("/favicon.ico").is_none());
59	    }
60	}
