335	/// One request with any headers over a fresh pinned connection.
336	fn http_with(
337	    addr: SocketAddr,
338	    config: &Arc<ClientConfig>,
339	    method: &str,
340	    path: &str,
341	    headers: &[(&str, &str)],
342	    body: &str,
343	) -> std::io::Result<Response> {
344	    let tcp = TcpStream::connect(addr)?;
345	    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
346	    let conn = ClientConnection::new(
347	        Arc::clone(config),
348	        ServerName::try_from("localhost").unwrap(),
349	    )
350	    .map_err(std::io::Error::other)?;
351	    let mut s = StreamOwned::new(conn, tcp);
352	    while s.conn.is_handshaking() {
353	        s.conn.complete_io(&mut s.sock)?;
354	    }
355	    let extra = headers.iter().fold(String::new(), |mut s, (n, v)| {
356	        use std::fmt::Write as _;
357	        let _ = write!(s, "{n}: {v}\r\n");
358	        s
359	    });
360	    write!(
361	        s,
362	        "{method} {path} HTTP/1.1\r\nHost: localhost\r\n{extra}Content-Length: {}\r\n\r\n{body}",
363	        body.len()
364	    )?;
365	    s.flush()?;
366	    let mut reader = BufReader::new(s);
367	    let mut line = String::new();
368	    reader.read_line(&mut line)?;
369	    let status: u16 = line
370	        .split_whitespace()
371	        .nth(1)
372	        .and_then(|s| s.parse().ok())
373	        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
374	    let mut out_headers = Vec::new();
375	    let mut length = 0usize;
376	    loop {
377	        let mut h = String::new();
378	        reader.read_line(&mut h)?;
379	        let h = h.trim_end();
380	        if h.is_empty() {
381	            break;
382	        }
383	        if let Some((n, v)) = h.split_once(':') {
384	            let (n, v) = (n.trim().to_ascii_lowercase(), v.trim().to_owned());
385	            if n == "content-length" {
386	                length = v.parse().unwrap_or(0);
387	            }
388	            out_headers.push((n, v));
389	        }
390	    }
391	    let mut out = vec![0; length];
392	    reader.read_exact(&mut out)?;
393	    Ok((
394	        status,
395	        out_headers,
396	        String::from_utf8_lossy(&out).into_owned(),
397	    ))
398	}
