400	/// `http_with` from a client thread, the app serving on this one.
401	fn call_with(
402	    port: &mut Port,
403	    method: &str,
404	    path: &str,
405	    headers: &[(&str, &str)],
406	    body: &str,
407	) -> Response {
408	    let addr = port.addr;
409	    let config = Arc::clone(&port.client);
410	    let (method, path, body) = (method.to_owned(), path.to_owned(), body.to_owned());
411	    let headers: Vec<(String, String)> = headers
412	        .iter()
413	        .map(|(n, v)| ((*n).to_owned(), (*v).to_owned()))
414	        .collect();
415	    let client = std::thread::spawn(move || {
416	        let borrowed: Vec<(&str, &str)> = headers
417	            .iter()
418	            .map(|(n, v)| (n.as_str(), v.as_str()))
419	            .collect();
420	        http_with(addr, &config, &method, &path, &borrowed, &body)
421	    });
422	    let deadline = std::time::Instant::now() + Duration::from_secs(5);
423	    while !client.is_finished() {
424	        assert!(std::time::Instant::now() < deadline, "no reply");
425	        port.app.serve_pending();
426	        std::thread::sleep(Duration::from_millis(2));
427	    }
428	    client.join().unwrap().expect("http")
429	}
