440	/// header whole and the reply envelope.
441	fn pair_by_cookie(
442	    port: &mut Port,
443	    code: &str,
444	    scope: Scope,
445	    name: &str,
446	) -> (String, serde_json::Value) {
447	    port.app.dispatch(AppAction::OpenPairing {
