/// Whether the request's `Origin` is the page's own: `https://` and
/// the `Host` header, which is what a browser sends from the page.
fn origin_is_own(request: &RemoteRequest) -> bool {
    match (&request.origin, &request.host) {
        (Some(origin), Some(host)) => {
            origin.strip_prefix("https://").map(str::trim) == Some(host.trim())
        }
        _ => false,
    }
}

/// The paired device behind a request's credential, seen now; or
/// the refusal, which says nothing of the host. The credential is
/// the bearer header, or without one the host's own cookie, which
/// a browser sends on its own. A cookie is sent by the browser on
/// any same-site request, so a cookie-authenticated write or
/// upgrade must also carry the page's `Origin`: `SameSite=Strict`
/// withholds the cookie cross-site, and this closes the same-site,
/// other-port case. A native client sends no `Origin` and needs
/// none.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let (token, by_cookie) = match &request.bearer {
        Some(token) => (token.clone(), false),
        None => match self.cookie_token(request) {
            Some(token) => (token, true),
            None => {
                return Err(self.refuse(
                    request,
                    401,
                    "unauthorized",
                    "pair this device first",
                    false,
                ));
            }
        },
    };
    let Some(device) = self
        .core
        .device_by_token(&remote::token_sha256(&token))
        .cloned()
    else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "the token is not known; pair again",
            false,
        ));
    };
    if by_cookie
        && (request.method != "GET" || request.upgrade.is_some())
        && !Self::origin_is_own(request)
    {
        return Err(self.refuse(
            request,
            403,
            "origin",
            "a browser's write must come from the page itself",
            false,
        ));
    }
    self.dispatch_inner(AppAction::DeviceSeen(device.id));
    Ok(device)
}

/// The value of this host's cookie in the request, by exact name;
/// every other cookie is ignored.
fn cookie_token(&self, request: &RemoteRequest) -> Option<String> {
    let header = request.cookie.as_deref()?;
    let name = self.cookie_name()?;
    header
        .split(';')
        .filter_map(|pair| pair.trim().split_once('='))
        .find(|(n, _)| *n == name)
        .map(|(_, v)| v.trim().to_owned())
        .filter(|v| !v.is_empty())
}

/// The cookie's name carries the server id: cookies ignore ports,
/// so two instances on one Mac share a jar for the page's host and
/// a fixed name would have the second pairing overwrite the first.
/// The id is stable across a key rotation, so a rotation does not
/// orphan the cookie. `__Host-` makes the browser enforce `Secure`,
/// `Path=/` and no `Domain`.
fn cookie_name(&self) -> Option<String> {
    self.core
        .identity()
        .map(|identity| format!("__Host-sb-{}", identity.server_id))
}

